/*
 * A090821  Numbers that are products of two consecutive nonprimes.
 * https://oeis.org/A090821
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = nonprimes(n-1) * nonprimes(n) where nonprimes(k) is the
 *            k‑th integer ≥1 that is not prime (nonprime list:
 *            1,4,6,8,9,10,12,14,...). The sequence is generated by an
 *            on‑demand sieve of primality with trial division
 * Range:     u8 n <= 9, u16 n <= 47, u32 n <= 47, u64 n <= 47, u128 n <= 47,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

static bool is_prime(idx_t x)
{
    if (x < 2) return false;
    if (x % 2 == 0) return x == 2;
    if (x % 3 == 0) return x == 3;
    for (idx_t d = 5; d * d <= x; d += 6) {
        if (x % d == 0) return false;
        if (x % (d + 2) == 0) return false;
    }
    return true;
}

seq_t a(idx_t n)
{
    /* static state */
    static uint64_t *nonprimes = NULL;
    static size_t np_len = 0, np_cap = 0;
    static idx_t processed_limit = 1; /* numbers 1..processed_limit have been examined */

    /* initialise list with the first nonprime, 1 */
    if (np_len == 0) {
        np_cap = 8;
        nonprimes = (uint64_t *)malloc(np_cap * sizeof(uint64_t));
        if (!nonprimes) return (seq_t)0; /* out of memory, safe fallback */
        nonprimes[0] = 1;
        np_len = 1;
    }

    /* grow list until we have at least n+1 nonprimes (a(n) uses indices n-1 and n) */
    while (np_len < n + 1) {
        /* check next integer for primality */
        processed_limit++;
        if (!is_prime(processed_limit)) {
            /* add to list */
            if (np_len >= np_cap) {
                np_cap = np_cap * 2;
                uint64_t *tmp = (uint64_t *)realloc(nonprimes, np_cap * sizeof(uint64_t));
                if (!tmp) return (seq_t)0; /* out of memory, safe fallback */
                nonprimes = tmp;
            }
            nonprimes[np_len++] = (uint64_t)processed_limit;
        }
    }

    /* compute the product in the output type */
    return (seq_t)(nonprimes[n - 1]) * (seq_t)(nonprimes[n]);
}
